function recoveryWhatsAppLink(cart,settings){const link=customerWhatsAppLink({whatsapp:cart&&cart.whatsapp});if(!link)return '';const name=cleanText(cart&&cart.name);const message='Olá'+(name?', '+name:'')+'! Você começou a criar um livro personalizado na '+settings.shop+' e o pedido não foi finalizado. Se quiser, posso te ajudar a concluir de onde você parou.';return link+'?text='+encodeURIComponent(message)}
function minutesSince(value){const time=new Date(value||0).getTime();if(!Number.isFinite(time))return 0;return Math.max(0,Math.floor((Date.now()-time)/60000))}
const FC_TIME_ZONE='America/Fortaleza';
function formatFortalezaDateTime(value){
  const d=new Date(value||0);
  if(Number.isNaN(d.getTime()))return '—';
  return new Intl.DateTimeFormat('pt-BR',{
    timeZone:FC_TIME_ZONE,
    day:'2-digit',month:'2-digit',year:'numeric',
    hour:'2-digit',minute:'2-digit',second:'2-digit',
    hour12:false
  }).format(d)+' · Fortaleza/CE';
}
function fortalezaDateKey(value){
  const d=new Date(value||0);
  if(Number.isNaN(d.getTime()))return '';
  const parts=new Intl.DateTimeFormat('en-CA',{timeZone:FC_TIME_ZONE,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);
  const map=Object.fromEntries(parts.map(part=>[part.type,part.value]));
  return map.year+'-'+map.month+'-'+map.day;
}


