function adminNavHtml(settings,adminToken,active){const base='/painel?token='+encodeURIComponent(adminToken);return '<aside class="admin-sidebar"><div class="side-brand"><div class="admin-logo">FC</div><div><strong>FC Artes Digitais</strong><small>Painel de prévias</small></div></div><nav class="admin-nav"><a class="'+(active==='quiz-clients'?'active':'')+'" href="'+base+'">👥 Clientes / Fotos</a><a class="'+(active==='previews'?'active':'')+'" href="'+base+'&view=previews">🖼 Todas as prévias</a><a class="'+(active==='settings'?'active':'')+'" href="'+base+'&view=config">⚙ Configurações</a><a href="/quiz" target="_blank" rel="noopener">↗ Abrir quiz</a></nav><div class="admin-side-foot">FC Artes Digitais<br>Armazenamento persistente Supabase</div></aside>'}
function adminLayoutHtml(content,settings,adminToken,active,title,script){return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>'+escapeHtml(title)+' — '+escapeHtml(settings.shop)+'</title><style>'+ORDER_CSS+ADMIN_CSS+ADMIN_CART_CSS+ADMIN_PREVIEW_CSS+ADMIN_QUIZ_CLIENT_CSS+ADMIN_QUIZ_RATE_CSS+ADMIN_CRM_CSS+'</style></head><body class="admin-body"><div class="admin-layout">'+adminNavHtml(settings,adminToken,active)+'<div class="admin-main"><header class="admin-topbar"><div><strong>'+escapeHtml(title)+'</strong></div><div class="admin-topmeta">'+(settings.whatsapp?'WhatsApp: '+escapeHtml(settings.whatsapp):'WhatsApp não configurado')+' · '+escapeHtml(settings.price)+'</div></header><main class="admin-shell">'+content+'</main></div></div>'+(script||'')+'</body></html>'}
const ADMIN_PREVIEW_CSS='.preview-admin-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(290px,1fr));gap:16px;margin-top:18px}.preview-admin-card{background:#fff;border:1px solid #e5e7eb;border-radius:17px;overflow:hidden;box-shadow:0 1px 2px rgba(15,23,42,.04)}.preview-admin-images{display:grid;grid-template-columns:1fr 1fr;background:#111827;min-height:180px}.preview-admin-image{position:relative;min-width:0}.preview-admin-image img{width:100%;height:220px;object-fit:cover;display:block;background:#111}.preview-admin-label{position:absolute;left:8px;bottom:8px;background:rgba(15,23,42,.82);color:#fff;border-radius:999px;padding:5px 8px;font-size:10px;font-weight:850}.preview-admin-body{padding:15px}.preview-admin-title{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.preview-admin-title strong{font-size:15px}.preview-admin-meta{display:grid;gap:5px;margin:10px 0 13px;color:#6b7280;font-size:12px}.preview-admin-actions{display:flex;gap:8px;flex-wrap:wrap}.preview-admin-actions a{flex:1;text-align:center}.preview-empty{background:#fff;border:1px solid #e5e7eb;border-radius:16px;padding:42px;text-align:center;color:#6b7280}@media(max-width:560px){.preview-admin-images{grid-template-columns:1fr}.preview-admin-image img{height:260px}}';
const ADMIN_QUIZ_CLIENT_CSS='.quiz-client-toolbar{display:grid;grid-template-columns:2fr 1.2fr .8fr 1fr;gap:10px;margin:18px 0}.quiz-client-toolbar input,.quiz-client-toolbar select{width:100%;border:1px solid #dfe3ea;border-radius:11px;padding:11px 12px;background:#fff;font:inherit;color:#111827}.quiz-client-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:16px}.quiz-client-card{background:#fff;border:1px solid #e5e7eb;border-radius:17px;overflow:hidden;box-shadow:0 1px 2px rgba(15,23,42,.04)}.quiz-client-head{padding:14px 15px 0;display:flex;justify-content:space-between;gap:12px}.quiz-client-name{font-weight:900;font-size:16px}.quiz-client-phone{font-size:12px;color:#64748b;margin-top:3px}.quiz-client-meta{padding:12px 15px;display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:12px;color:#64748b}.quiz-client-meta strong{color:#111827;display:block;margin-bottom:2px}.quiz-client-actions{padding:0 15px 15px;display:flex;gap:8px;flex-wrap:wrap}.quiz-client-actions a{flex:1;text-align:center;min-width:105px}.quiz-client-actions .wa-client{background:#16a34a;color:#fff;border-color:#16a34a}.quiz-client-count{font-size:13px;color:#64748b;margin:0 0 12px}.quiz-client-empty{background:#fff;border:1px solid #e5e7eb;border-radius:16px;padding:42px;text-align:center;color:#6b7280}@media(max-width:760px){.quiz-client-toolbar{grid-template-columns:1fr 1fr}.quiz-client-grid{grid-template-columns:1fr}}@media(max-width:480px){.quiz-client-toolbar{grid-template-columns:1fr}.quiz-client-meta{grid-template-columns:1fr}}';
const ADMIN_CRM_CSS='.crm-row{padding:0 15px 14px;display:flex;align-items:center;gap:9px}.crm-row label{font-size:11px;font-weight:900;color:#64748b}.crm-select{flex:1;border:1px solid #dbe1ea;border-radius:10px;padding:9px 10px;background:#fff;font:inherit;font-size:12px;font-weight:800}.crm-badge{border-radius:999px;padding:5px 9px;font-size:10px;font-weight:900;text-transform:uppercase}.crm-nova{background:#ede9fe;color:#6d28d9}.crm-chamado{background:#e0f2fe;color:#0369a1}.crm-pagou{background:#dcfce7;color:#15803d}.crm-entregue{background:#ecfccb;color:#3f6212}.today-strip{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:14px 0 18px}.today-card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:13px}.today-card span{display:block;color:#64748b;font-size:11px}.today-card strong{display:block;margin-top:4px;font-size:22px}@media(max-width:640px){.today-strip{grid-template-columns:1fr 1fr}}';
const ADMIN_QUIZ_RATE_CSS='.quiz-access{margin:0 15px 12px;padding:11px 12px;border-radius:12px;background:#f8fafc;border:1px solid #e5e7eb}.quiz-access-row{display:flex;justify-content:space-between;gap:10px;align-items:center}.quiz-access-state{font-size:12px;font-weight:900}.quiz-access-state.auto{color:#7c3aed}.quiz-access-state.allowed{color:#15803d}.quiz-access-state.blocked{color:#b91c1c}.quiz-access small{display:block;color:#64748b;margin-top:4px}.quiz-access-actions{display:flex;gap:6px;margin-top:9px;flex-wrap:wrap}.quiz-access-actions button{border:1px solid #dbe1ea;border-radius:9px;background:#fff;padding:7px 9px;font:inherit;font-size:11px;font-weight:850;cursor:pointer}.quiz-access-actions button[data-mode="allowed"]{color:#15803d}.quiz-access-actions button[data-mode="blocked"]{color:#b91c1c}.quiz-access-actions button.active{background:#111827;color:#fff;border-color:#111827}.quiz-rate-help{margin:12px 0 18px;padding:12px 14px;border-radius:12px;background:#f5f3ff;color:#5b21b6;font-size:12px}';
function previewAdminHtml(list,settings,adminToken){const safe=(Array.isArray(list)?list:[]).filter(Boolean);const cards=safe.map(item=>{const q='?token='+encodeURIComponent(adminToken)+'&id='+encodeURIComponent(item.id);const original='/api/admin/preview-image'+q+'&kind=original';const preview='/api/admin/preview-image'+q+'&kind=preview';return '<article class="preview-admin-card"><div class="preview-admin-images">'+(item.hasOriginal?'<div class="preview-admin-image"><img loading="lazy" src="'+original+'" alt="Foto original"><span class="preview-admin-label">ORIGINAL</span></div>':'')+(item.hasPreview?'<div class="preview-admin-image"><img loading="lazy" src="'+preview+'" alt="Prévia gerada"><span class="preview-admin-label">GERADA</span></div>':'')+'</div><div class="preview-admin-body"><div class="preview-admin-title"><strong>#'+escapeHtml(item.id)+'</strong><span class="status-pill status-enviado">'+escapeHtml(item.status||'gerada')+'</span></div><div class="preview-admin-meta"><span><strong>Tipo:</strong> '+escapeHtml(item.type||'—')+'</span><span><strong>Estilo:</strong> '+escapeHtml(item.style||'—')+'</span><span><strong>Modelo:</strong> '+escapeHtml(item.model||'—')+'</span><span><strong>Data:</strong> '+escapeHtml(formatFortalezaDateTime(item.createdAt))+'</span></div><div class="preview-admin-actions">'+(item.hasOriginal?'<a class="mini-btn" target="_blank" href="'+original+'">Original</a>':'')+(item.hasPreview?'<a class="mini-btn" target="_blank" href="'+preview+'">Prévia</a><a class="mini-btn" href="'+preview+'&download=1">⬇ Download</a>':'')+'<a class="mini-btn danger" href="/painel?token='+encodeURIComponent(adminToken)+'&view=previews&apagarPreview='+encodeURIComponent(item.id)+'" onclick="return confirm(\'Apagar esta geração e as duas imagens?\')">Apagar</a></div></div></article>'}).join('');const content='<div class="admin-heading"><div><h1>Prévias geradas por IA</h1><p>Fotos enviadas no quiz e resultados produzidos pela QuackAPI.</p></div><div>'+(settings.storagePersistent?'<span class="storage-ok">● Supabase permanente</span>':'<span class="storage-warn">● Armazenamento temporário</span>')+'</div></div><section class="metrics"><div class="metric"><span>Prévias salvas</span><strong>'+safe.length+'</strong></div><div class="metric"><span>Com original</span><strong>'+safe.filter(x=>x.hasOriginal).length+'</strong></div><div class="metric"><span>Com resultado</span><strong>'+safe.filter(x=>x.hasPreview).length+'</strong></div></section>'+(cards?'<section class="preview-admin-grid">'+cards+'</section>':'<div class="preview-empty"><strong>Nenhuma prévia salva ainda.</strong><br>As próximas gerações do quiz aparecerão aqui automaticamente.</div>');return adminLayoutHtml(content,settings,adminToken,'previews','Prévias IA')}
function quizClientsAdminHtml(list,settings,adminToken,journeyAnalytics){
  const safe=(Array.isArray(list)?list:[]).filter(Boolean);
  const styleOf=item=>cleanText(item&&item.style).replace(/\s*·\s*Posição\s*\d+\s*$/i,'')||'—';
  const poseOf=item=>cleanText(item&&item.pose)||((cleanText(item&&item.style).match(/Posição\s*(\d+)/i)||[])[1]||'');
  const styles=[...new Set(safe.map(styleOf).filter(value=>value&&value!=='—'))].sort((a,b)=>a.localeCompare(b,'pt-BR'));
  const todayKey=fortalezaDateKey(new Date());
  const todayItems=safe.filter(item=>fortalezaDateKey(item.createdAt)===todayKey);
  const crmOf=item=>['nova','chamado','pagou','entregue'].includes(cleanText(item&&item.crmStatus).toLowerCase())?cleanText(item.crmStatus).toLowerCase():'nova';
  const cards=safe.map(item=>{
    const style=styleOf(item),pose=poseOf(item),name=cleanText(item.customerName)||'Cliente sem nome',phone=cleanText(item.customerWhatsapp),crm=crmOf(item);
    const q='?token='+encodeURIComponent(adminToken)+'&id='+encodeURIComponent(item.id);
    const original='/api/admin/preview-image'+q+'&kind=original';
    const preview='/api/admin/preview-image'+q+'&kind=preview';
    const waBase=phone?customerWhatsAppLink({whatsapp:phone}):'';
    const waMessage='Olá'+(name&&name!=='Cliente sem nome'?', '+name:'')+'! Vi sua prévia '+style+(pose?' (posição '+pose+')':'')+' na FC Artes Digitais. Posso te ajudar a receber a versão final sem marca d’água?';
    const wa=waBase?waBase+'?text='+encodeURIComponent(waMessage):'';
    const dateObj=new Date(item.createdAt||0),dateKey=fortalezaDateKey(item.createdAt);
    const search=[item.id,name,phone,item.type,style,pose,crm].join(' ').toLowerCase();
    const access=item.generationAccess||null,mode=access&&access.mode?access.mode:'auto',count=access?Number(access.count)||0:0;
    const modeLabel=mode==='allowed'?'LIBERADO':mode==='blocked'?'BLOQUEADO':'AUTOMÁTICO';
    const accessHtml=item.sessionToken?'<div class="quiz-access" data-access-box><div class="quiz-access-row"><strong>Gerações</strong><span class="quiz-access-state '+mode+'">'+modeLabel+'</span></div><small>'+count+' geração'+(count===1?'':'ões')+' hoje · padrão 3/dia</small><div class="quiz-access-actions"><button type="button" data-access-mode="auto" data-session="'+escapeHtml(item.sessionToken)+'" class="'+(mode==='auto'?'active':'')+'">Automático</button><button type="button" data-access-mode="allowed" data-session="'+escapeHtml(item.sessionToken)+'" class="'+(mode==='allowed'?'active':'')+'">Liberar</button><button type="button" data-access-mode="blocked" data-session="'+escapeHtml(item.sessionToken)+'" class="'+(mode==='blocked'?'active':'')+'">Bloquear</button></div></div>':'';
    const crmSelect='<div class="crm-row"><label>STATUS</label><select class="crm-select" data-crm-id="'+escapeHtml(item.id)+'"><option value="nova"'+(crm==='nova'?' selected':'')+'>Nova prévia</option><option value="chamado"'+(crm==='chamado'?' selected':'')+'>Cliente chamado</option><option value="pagou"'+(crm==='pagou'?' selected':'')+'>Pagou</option><option value="entregue"'+(crm==='entregue'?' selected':'')+'>Entregue</option></select><span class="crm-badge crm-'+crm+'">'+crm+'</span></div>';
    return '<article class="quiz-client-card" data-quiz-client data-search="'+escapeHtml(search)+'" data-style="'+escapeHtml(style)+'" data-pose="'+escapeHtml(pose)+'" data-date="'+escapeHtml(dateKey)+'"><div class="preview-admin-images">'+(item.hasOriginal?'<div class="preview-admin-image"><img loading="lazy" src="'+original+'" alt="Foto original"><span class="preview-admin-label">ORIGINAL</span></div>':'')+(item.hasPreview?'<div class="preview-admin-image"><img loading="lazy" src="'+preview+'" alt="Resultado gerado"><span class="preview-admin-label">RESULTADO</span></div>':'')+'</div><div class="quiz-client-head"><div><div class="quiz-client-name">'+escapeHtml(name)+'</div><div class="quiz-client-phone">'+escapeHtml(phone||'WhatsApp não informado')+'</div></div><span class="crm-badge crm-'+crm+'">'+crm+'</span></div><div class="quiz-client-meta"><div><strong>Estilo</strong>'+escapeHtml(style)+'</div><div><strong>Posição</strong>'+(pose?'Posição '+escapeHtml(pose):'—')+'</div><div><strong>Tipo</strong>'+escapeHtml(item.type||'—')+'</div><div><strong>Data</strong>'+escapeHtml(formatFortalezaDateTime(item.createdAt))+'</div></div>'+crmSelect+accessHtml+'<div class="quiz-client-actions">'+(wa?'<a class="mini-btn wa-client" target="_blank" rel="noopener" href="'+escapeHtml(wa)+'">💬 WhatsApp</a>':'')+(item.hasOriginal?'<a class="mini-btn" target="_blank" href="'+original+'">Original</a>':'')+(item.hasPreview?'<a class="mini-btn" target="_blank" href="'+preview+'">Resultado</a><a class="mini-btn" href="'+preview+'&download=1">⬇ Download</a>':'')+'<a class="mini-btn danger" href="/painel?token='+encodeURIComponent(adminToken)+'&view=quiz-clients&apagarPreview='+encodeURIComponent(item.id)+'" onclick="return confirm(\'Apagar esta geração e as imagens?\')">Apagar</a></div></article>';
  }).join('');
  const toolbar='<section class="quiz-client-toolbar"><input id="quiz-client-search" type="search" placeholder="Buscar cliente, WhatsApp ou ID"><select id="quiz-style-filter"><option value="">Todos os estilos</option>'+styles.map(style=>'<option value="'+escapeHtml(style)+'">'+escapeHtml(style)+'</option>').join('')+'</select><select id="quiz-pose-filter"><option value="">Todas as poses</option><option value="1">Posição 1</option><option value="2">Posição 2</option><option value="3">Posição 3</option><option value="4">Posição 4</option><option value="5">Posição 5</option></select><input id="quiz-date-filter" type="date" aria-label="Filtrar por data em Fortaleza"></section>';
  const todayStrip='<section class="today-strip"><div class="today-card"><span>Prévias hoje</span><strong>'+todayItems.length+'</strong></div><div class="today-card"><span>Novas</span><strong>'+safe.filter(x=>crmOf(x)==='nova').length+'</strong></div><div class="today-card"><span>Pagaram</span><strong>'+safe.filter(x=>crmOf(x)==='pagou').length+'</strong></div><div class="today-card"><span>Entregues</span><strong>'+safe.filter(x=>crmOf(x)==='entregue').length+'</strong></div></section>';
  const script='<script>(function(){var search=document.getElementById("quiz-client-search"),style=document.getElementById("quiz-style-filter"),pose=document.getElementById("quiz-pose-filter"),date=document.getElementById("quiz-date-filter"),count=document.getElementById("quiz-client-visible");function apply(){var q=(search.value||"").trim().toLowerCase(),sv=style.value||"",pv=pose.value||"",dv=date.value||"",shown=0;document.querySelectorAll("[data-quiz-client]").forEach(function(card){var ok=(!q||(card.dataset.search||"").includes(q))&&(!sv||card.dataset.style===sv)&&(!pv||card.dataset.pose===pv)&&(!dv||card.dataset.date===dv);card.style.display=ok?"":"none";if(ok)shown++});count.textContent=shown+" cliente"+(shown===1?"":"s")+" visível"+(shown===1?"":"eis")}[search,style,pose,date].forEach(function(el){el.addEventListener("input",apply);el.addEventListener("change",apply)});document.addEventListener("click",function(e){var b=e.target.closest("[data-access-mode]");if(!b)return;b.disabled=true;fetch("/api/admin/quiz-access?token='+encodeURIComponent(adminToken)+'",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({sessionToken:b.dataset.session,mode:b.dataset.accessMode})}).then(function(r){return r.json().then(function(j){return {ok:r.ok,data:j}})}).then(function(result){if(!result.ok)throw new Error(result.data&&result.data.error?result.data.error:"Falha ao alterar acesso");window.location.reload()}).catch(function(err){b.disabled=false;alert(err.message)})});document.addEventListener("change",function(e){var sel=e.target.closest("[data-crm-id]");if(!sel)return;sel.disabled=true;fetch("/api/admin/preview-status?token='+encodeURIComponent(adminToken)+'",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({id:sel.dataset.crmId,status:sel.value})}).then(function(r){return r.json().then(function(j){return {ok:r.ok,data:j}})}).then(function(result){if(!result.ok)throw new Error(result.data&&result.data.error?result.data.error:"Falha ao atualizar status");window.location.reload()}).catch(function(err){sel.disabled=false;alert(err.message)})});apply()})()</script>';
  const journey=journeyAnalytics||{counts:{},sources:[],devices:{},recent:[]},jc=journey.counts||{},base=Math.max(1,Number(jc.visitors)||0),pct=value=>Math.round((Number(value)||0)/base*100);
  const quizFunnel=[['Visitantes',Number(jc.visitors)||0],['Iniciaram',Number(jc.started)||0],['Tentaram gerar',Number(jc.generated)||0],['Prévia pronta',Number(jc.previewed)||0],['Checkout exibido',Number(jc.checkout)||0],['Clique para pagar',Number(jc.paymentClicks)||0]];
  const quizFunnelHtml=quizFunnel.map(item=>'<div class="funnel-row"><div class="funnel-name"><strong>'+escapeHtml(item[0])+'</strong><small>'+pct(item[1])+'% dos visitantes</small></div><div class="funnel-track"><div class="funnel-fill" style="width:'+Math.max(0,Math.min(100,pct(item[1])))+'%"></div></div><div class="funnel-value">'+item[1]+'<small>'+pct(item[1])+'%</small></div></div>').join('');
  const sourceHtml=(journey.sources||[]).map(item=>'<tr><td>'+escapeHtml(item.name)+'</td><td><strong>'+Number(item.count||0)+'</strong></td></tr>').join('')||'<tr><td colspan="2">Sem origem registrada ainda.</td></tr>';
  const deviceData=journey.devices||{},deviceHtml=['Celular','Desktop','Tablet'].map(name=>'<div class="today-card"><span>'+name+'</span><strong>'+Number(deviceData[name]||0)+'</strong></div>').join('');
  const recentHtml=(journey.recent||[]).map(item=>{const ev=item.events||{},stage=ev.payment_click?'Clique pagamento':ev.checkout_view?'Checkout':ev.preview?'Prévia':ev.generate?'Gerando':ev.start?'Iniciou':'Visitou',campaign=item.campaign?' · '+item.campaign:'';return '<tr><td>'+escapeHtml(formatFortalezaDateTime(item.lastAt))+'</td><td>'+escapeHtml(item.device||'—')+'</td><td>'+escapeHtml((item.source||'Direto')+campaign)+'</td><td>'+escapeHtml(stage)+'</td><td>'+Number(item.visitCount||0)+'</td></tr>'}).join('')||'<tr><td colspan="5">As próximas visitas aparecerão aqui.</td></tr>';
  const analyticsSection='<section class="funnel-wrap"><div class="funnel-card"><h2>Funil do Quiz de Fotos</h2><p>Visitantes únicos por sessão. “Checkout exibido” significa que a tela de pagamento apareceu após a prévia.</p><div class="today-strip"><div class="today-card"><span>Visitantes únicos</span><strong>'+Number(jc.visitors||0)+'</strong></div><div class="today-card"><span>Visualizações</span><strong>'+Number(jc.pageviews||0)+'</strong></div><div class="today-card"><span>Visitantes hoje</span><strong>'+Number(jc.todayVisitors||0)+'</strong></div><div class="today-card"><span>Prévia pronta</span><strong>'+Number(jc.previewed||0)+'</strong></div></div><div class="funnel-list">'+quizFunnelHtml+'</div><h3 style="margin:22px 0 8px">Dispositivos</h3><div class="today-strip">'+deviceHtml+'</div><h3 style="margin:22px 0 8px">Origem / UTM</h3><section class="admin-table-card"><table class="admin-table"><thead><tr><th>Origem</th><th>Visitantes</th></tr></thead><tbody>'+sourceHtml+'</tbody></table></section><h3 style="margin:22px 0 8px">Últimas visitas</h3><section class="admin-table-card"><table class="admin-table"><thead><tr><th>Horário Fortaleza</th><th>Dispositivo</th><th>Origem</th><th>Etapa</th><th>Acessos</th></tr></thead><tbody>'+recentHtml+'</tbody></table></section></div></section>';
  
  const content='<div class="admin-heading"><div><h1>Clientes e Prévias</h1><p>Seu mini CRM: acompanhe cada cliente da prévia até a entrega final. Datas e horários em Fortaleza/CE.</p></div><div>'+(settings.storagePersistent?'<span class="storage-ok">● Supabase permanente</span>':'<span class="storage-warn">● Armazenamento temporário</span>')+'</div></div>'+analyticsSection+todayStrip+toolbar+'<p class="quiz-client-count" id="quiz-client-visible"></p>'+(cards?'<section class="quiz-client-grid">'+cards+'</section>':'<div class="quiz-client-empty"><strong>Nenhuma prévia ainda.</strong><br>As novas gerações aparecerão aqui automaticamente.</div>');
  return adminLayoutHtml(content,settings,adminToken,'quiz-clients','Clientes e Prévias',script);
}
function adminSettingsHtml(settings,adminToken,info){const persistent=Boolean(settings.storagePersistent);const cloudWa=Boolean(settings.token&&settings.phoneId&&settings.whatsapp);const ai=Boolean(info&&info.aiConfigured);const form='<section class="settings-card"><h2>Dados da loja</h2><p>Altere as informações usadas nos pedidos e no contato com clientes.</p><form class="settings-form" id="admin-settings-form"><label>Nome da loja<input name="shop" maxlength="80" value="'+escapeHtml(settings.shop)+'"></label><label>WhatsApp da loja<input name="whatsapp" maxlength="20" inputmode="tel" value="'+escapeHtml(settings.whatsapp)+'" placeholder="5585999999999"></label><label>Preço da foto final<input name="price" maxlength="40" value="'+escapeHtml(settings.price)+'" placeholder="R$ 49,90"></label><label>Chave Pix<input name="pix" maxlength="160" value="'+escapeHtml(settings.pix)+'" placeholder="CPF, telefone, e-mail ou chave aleatória"></label><label>Pix Copia e Cola<textarea name="pixCopyPaste" maxlength="1200" placeholder="Cole aqui o código Pix Copia e Cola gerado pelo seu banco">'+escapeHtml(settings.pixCopyPaste||'')+'</textarea><small class="note">O cliente poderá copiar este código e pagar imediatamente no app do banco.</small></label><div class="settings-actions"><button class="settings-save" type="submit">Salvar configurações</button><span class="note" id="settings-status"></span></div></form>'+(persistent?'':'<div class="settings-note warn" style="margin-top:16px"><strong>Atenção:</strong> o Vercel Blob ainda não está conectado. Alterações feitas aqui podem desaparecer após uma reinicialização ou novo deploy.</div>')+'</section>';const integrations='<section class="settings-card"><h2>Integrações e segurança</h2><p>Visão geral das conexões do sistema. Segredos nunca são exibidos.</p><div class="integration-list"><div class="integration"><div><strong>Armazenamento persistente</strong><small>Guarda clientes, prévias, fotos e configurações.</small></div><span class="signal '+(persistent?'ok':'warn')+'">'+(persistent?'ATIVO':'PENDENTE')+'</span></div><div class="integration"><div><strong>Proteção do administrador</strong><small>Acesso ao painel protegido por token privado.</small></div><span class="signal '+(settings.admin?'ok':'off')+'">'+(settings.admin?'ATIVA':'INATIVA')+'</span></div><div class="integration"><div><strong>WhatsApp da loja</strong><small>Número usado para receber e responder pedidos.</small></div><span class="signal '+(settings.whatsapp?'ok':'off')+'">'+(settings.whatsapp?'ATIVO':'INATIVO')+'</span></div><div class="integration"><div><strong>WhatsApp Cloud API</strong><small>Envio automático pelo servidor, sem abrir o WhatsApp manualmente.</small></div><span class="signal '+(cloudWa?'ok':'off')+'">'+(cloudWa?'ATIVA':'NÃO CONFIGURADA')+'</span></div><div class="integration"><div><strong>IA para prévias</strong><small>Geração das prévias de fotos.</small></div><span class="signal '+(ai?'ok':'warn')+'">'+(ai?'CONFIGURADA':'DEMONSTRAÇÃO')+'</span></div></div></section>';const links='<section class="settings-card"><h2>Acessos rápidos</h2><p>Atalhos para as áreas usadas no dia a dia.</p><div class="quick-links"><a class="quick-link" href="/painel?token='+encodeURIComponent(adminToken)+'">Clientes / Prévias<small>Atendimento e indicadores</small></a><a class="quick-link" href="/" target="_blank" rel="noopener">Quiz público<small>Abrir geração de prévia</small></a></div></section>';const security='<section class="settings-card"><h2>Segurança</h2><p>Configurações sensíveis continuam na Vercel e não aparecem no painel.</p><div class="settings-note"><strong>ADMIN_TOKEN</strong>, <strong>ORDER_SECRET</strong>, tokens da WhatsApp Cloud API e chaves de IA não são mostrados ou salvos pelo formulário desta página.</div></section>';const script='<script>(function(){var form=document.getElementById("admin-settings-form"),status=document.getElementById("settings-status");form.addEventListener("submit",function(e){e.preventDefault();var button=form.querySelector("button");button.disabled=true;status.textContent="Salvando…";var body={};new FormData(form).forEach(function(v,k){body[k]=v});fetch("/api/admin/settings?token='+encodeURIComponent(adminToken)+'",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)}).then(function(r){return r.json().then(function(j){return {ok:r.ok,data:j}})}).then(function(result){button.disabled=false;if(result.ok){status.textContent="Configurações salvas.";setTimeout(function(){window.location.reload()},500)}else status.textContent=result.data&&result.data.error?result.data.error:"Não foi possível salvar."}).catch(function(){button.disabled=false;status.textContent="Não foi possível salvar."})})})()</script>';return adminLayoutHtml('<div class="admin-heading"><div><h1>Configurações</h1><p>Controle os dados comerciais e acompanhe a saúde das integrações.</p></div></div><div class="settings-grid"><div>'+form+'<div style="height:18px"></div>'+links+'</div><div>'+integrations+'<div style="height:18px"></div>'+security+'</div></div>',settings,adminToken,'settings','Configurações',script)}
function painelHtml(list,settings,adminToken,origin,drafts,analytics,funnel,quizAnalytics){const safeList=(Array.isArray(list)?list:[]).filter(Boolean);const safeDrafts=(Array.isArray(drafts)?drafts:[]).filter(Boolean);const abandoned=safeDrafts.filter(item=>minutesSince(item.updatedAt)>=30).sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt));const visitData=analytics||{total:0,today:0};const quizVisitData=quizAnalytics||{total:0,today:0};const counts={total:safeList.length,novo:0,producao:0,pago:0,enviado:0,abandonados:abandoned.length,visitas:Number(visitData.total)||0,hoje:Number(visitData.today)||0,quizVisitas:Number(quizVisitData.total)||0,quizHoje:Number(quizVisitData.today)||0};for(const item of safeList){if(item.status==='novo')counts.novo++;else if(item.status==='em produção')counts.producao++;else if(item.status==='pago')counts.pago++;else if(item.status==='enviado')counts.enviado++}const funnelData=funnel||{steps:[0,0,0,0,0],orders:0};const funnelLabels=['A criança','A história','Personagens','Personalização','Finalizar','Pedido enviado'];const funnelValues=[...(Array.isArray(funnelData.steps)?funnelData.steps.slice(0,5):[0,0,0,0,0]),Number(funnelData.orders)||0].map(value=>Number(value)||0);while(funnelValues.length<6)funnelValues.push(0);const funnelBase=Math.max(1,funnelValues[0]||0);const funnelRows=funnelLabels.map((label,index)=>{const value=funnelValues[index];const pct=Math.round(value/funnelBase*100);const previous=index===0?value:funnelValues[index-1];const advance=index===0?100:(previous?Math.round(value/previous*100):0);return '<div class="funnel-row"><div class="funnel-name"><strong>'+escapeHtml(label)+'</strong><small>'+(index===0?'entrada no funil':advance+'% avançaram da etapa anterior')+'</small></div><div class="funnel-track"><div class="funnel-fill" style="width:'+Math.max(0,Math.min(100,pct))+'%"></div></div><div class="funnel-value">'+value+'<small>'+pct+'%</small></div></div>'}).join('');let biggestDrop={from:'',to:'',drop:-1};for(let i=1;i<funnelValues.length;i++){const prev=funnelValues[i-1],curr=funnelValues[i];if(prev>0){const drop=Math.max(0,Math.round((prev-curr)/prev*100));if(drop>biggestDrop.drop)biggestDrop={from:funnelLabels[i-1],to:funnelLabels[i],drop}}}const funnelInsight=biggestDrop.drop>=0?'<div class="funnel-insight"><strong>Maior queda:</strong> '+escapeHtml(biggestDrop.from)+' → '+escapeHtml(biggestDrop.to)+' · '+biggestDrop.drop+'% não avançaram.</div>':'<div class="funnel-insight">Os dados do funil começam a aparecer conforme novas pessoas avançarem pelo formulário.</div>';const funnelSection='<section class="funnel-wrap"><div class="funnel-card"><h2>Funil de conversão</h2><p>Veja até onde as pessoas estão indo no formulário e onde mais desistem.</p><div class="funnel-list">'+funnelRows+'</div>'+funnelInsight+'</div></section>';const statusSlug=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,'-').toLowerCase();const rows=safeList.map(item=>{const whatsapp=cleanText(item.whatsapp);const wa=whatsapp?customerWhatsAppLink({whatsapp}):'';return '<tr data-order-row data-search="'+escapeHtml([item.code,item.name,whatsapp,item.theme,item.status].join(' ').toLowerCase())+'" data-status="'+escapeHtml(item.status||'')+'"><td><a class="order-link" href="'+escapeHtml(orderLink(item.code,adminToken))+'">#'+escapeHtml(item.code)+'</a></td><td><div class="client-name">'+escapeHtml(item.name||'Sem nome')+'</div><div class="muted">'+escapeHtml(item.theme||'Sem tema')+'</div></td><td>'+(wa?'<a class="wa-link" href="'+escapeHtml(wa)+'" target="_blank" rel="noopener">'+escapeHtml(whatsapp)+'</a>':'<span class="muted">Não informado</span>')+'</td><td>'+escapeHtml(new Date(item.createdAt).toLocaleString('pt-BR'))+'</td><td><span class="status-pill status-'+statusSlug(item.status)+'">'+escapeHtml(item.status||'novo')+'</span></td><td>'+escapeHtml(item.total||settings.price)+'</td><td><div class="row-actions"><a class="mini-btn" href="'+escapeHtml(orderLink(item.code,adminToken))+'">Abrir</a><a class="mini-btn danger" href="/painel?token='+encodeURIComponent(adminToken)+'&apagar='+encodeURIComponent(item.code)+'" onclick="return confirm(\'Apagar o pedido '+escapeHtml(item.code)+' e todas as fotos/respostas?\')">Apagar</a></div></td></tr>'}).join('');const cartRows=abandoned.map(item=>{const age=minutesSince(item.updatedAt);const recovery=recoveryWhatsAppLink(item,settings);const stepLabel=['A criança','A história','Personagens','Personalização','Finalizar'][Math.max(0,Math.min(4,Number(item.step)||0))]||'Briefing';return '<tr><td><strong>#'+escapeHtml(item.cartId||'RASCUNHO')+'</strong><div class="cart-age">'+(age<60?age+' min sem atividade':Math.floor(age/60)+' h sem atividade')+'</div></td><td><div class="client-name">'+escapeHtml(item.name||'Cliente não identificado')+'</div><div class="muted">'+escapeHtml(item.theme||'Tema ainda não escolhido')+'</div></td><td>'+escapeHtml(stepLabel)+'</td><td><div class="cart-progress"><span style="width:'+Math.max(1,Math.min(100,Number(item.progress)||0))+'%"></span></div><div class="cart-age">'+escapeHtml(String(item.progress||0))+'% preenchido</div></td><td>'+ (item.whatsapp?escapeHtml(item.whatsapp):'<span class="muted">Ainda não informado</span>') +'</td><td>'+(recovery?'<a class="mini-btn cart-recover" href="'+escapeHtml(recovery)+'" target="_blank" rel="noopener">Recuperar no WhatsApp</a>':'<span class="muted">Sem contato para recuperação</span>')+'</td></tr>'}).join('');const storage=settings.storagePersistent?'<span class="storage-ok">● Armazenamento persistente ativo</span>':'<span class="storage-warn">● Armazenamento temporário</span>';const panelScript='<script>(function(){var q=document.getElementById("admin-search"),f=document.getElementById("admin-status-filter"),rows=[].slice.call(document.querySelectorAll("[data-order-row]")),count=document.getElementById("admin-visible-count");function apply(){var term=(q.value||"").trim().toLowerCase(),status=f.value,visible=0;rows.forEach(function(row){var ok=(!term||row.dataset.search.indexOf(term)>-1)&&(!status||row.dataset.status===status);row.style.display=ok?"":"none";if(ok)visible++});count.textContent=visible+" pedido"+(visible===1?"":"s")+" exibido"+(visible===1?"":"s")}q.addEventListener("input",apply);f.addEventListener("change",apply);apply()})()</script>';const carts='<div class="cart-head" id="carrinhos"><div><h2>Carrinhos abandonados</h2><p>Rascunhos sem atividade há pelo menos 30 minutos e que ainda não viraram pedido.</p></div><div class="admin-count">'+counts.abandonados+' abandonado'+(counts.abandonados===1?'':'s')+'</div></div>'+(settings.storagePersistent?'':'<div class="cart-alert"><strong>Atenção:</strong> sem armazenamento persistente, os carrinhos podem desaparecer quando a função reiniciar ou houver novo deploy.</div>')+'<section class="admin-table-card">'+(cartRows?'<table class="admin-table"><thead><tr><th>Carrinho</th><th>Cliente</th><th>Etapa</th><th>Progresso</th><th>WhatsApp</th><th>Recuperação</th></tr></thead><tbody>'+cartRows+'</tbody></table>':'<div class="admin-empty"><strong>Nenhum carrinho abandonado agora.</strong><br>Rascunhos recentes só aparecem aqui depois de 30 minutos sem atividade.</div>')+'</section>';return adminLayoutHtml('<div class="admin-heading"><div><h1>Dashboard de pedidos</h1><p>Acompanhe clientes, briefings, fotos, produção e oportunidades de recuperação.</p></div><div>'+storage+'</div></div><section class="metrics"><div class="metric"><span>Visitas gerais</span><strong>'+counts.visitas+'</strong></div><div class="metric"><span>Hoje (geral)</span><strong>'+counts.hoje+'</strong></div><div class="metric"><span>Acessos Quiz</span><strong>'+counts.quizVisitas+'</strong></div><div class="metric"><span>Quiz hoje</span><strong>'+counts.quizHoje+'</strong></div><div class="metric"><span>Pedidos</span><strong>'+counts.total+'</strong></div><div class="metric"><span>Novos</span><strong>'+counts.novo+'</strong></div><div class="metric"><span>Em produção</span><strong>'+counts.producao+'</strong></div><div class="metric"><span>Pagos</span><strong>'+counts.pago+'</strong></div><div class="metric"><span>Enviados</span><strong>'+counts.enviado+'</strong></div><div class="metric"><span>Abandonados</span><strong>'+counts.abandonados+'</strong></div></section>'+funnelSection+'<section class="admin-toolbar"><input class="admin-input" id="admin-search" type="search" placeholder="Buscar por cliente, código, WhatsApp ou tema"><select class="admin-select" id="admin-status-filter"><option value="">Todos os status</option>'+ORDER_STATUSES.map(status=>'<option value="'+escapeHtml(status)+'">'+escapeHtml(status)+'</option>').join('')+'</select><div class="admin-count" id="admin-visible-count"></div></section><section class="admin-table-card" id="pedidos">'+(rows?'<table class="admin-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>WhatsApp</th><th>Recebido</th><th>Status</th><th>Valor</th><th>Ações</th></tr></thead><tbody>'+rows+'</tbody></table>':'<div class="admin-empty"><strong>Nenhum pedido recebido ainda.</strong><br>Os novos pedidos aparecerão aqui automaticamente.</div>')+'</section>'+carts+'<p class="note" style="margin-top:18px">Recuperações são manuais. Use o WhatsApp apenas quando o cliente tiver informado o número durante o preenchimento.</p>',settings,adminToken,'dashboard','Dashboard',panelScript)}
function orderNotFoundHtml(){return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Pedido não encontrado</title><style>'+ORDER_CSS+'</style></head><body><h1>Pedido não encontrado</h1><p class="note">Este link está incompleto, expirou ou o pedido foi apagado. Peça um novo link para a loja pelo WhatsApp.</p></body></html>'}
// Cenas de produção (briefing técnico): exibidas apenas na visão do administrador.
function briefingScenes(briefing){const data=briefing||{};const name=cleanText(data.name)||'a criança';const theme=(cleanText(data.theme)||'aventura').toLowerCase();const feeling=(cleanText(data.feeling)||'amizade').toLowerCase();const cast=(Array.isArray(data.cast)?data.cast:[]).map(item=>cleanText(item&&item.name)+(item&&item.detail?' ('+cleanText(item.detail)+')':''));const years=data.years===''||data.years===undefined?'':', '+data.years+' anos';const base=`Ilustração infantil em estilo ${cleanText(data.style)||'cartoon mágico'}. Personagem principal: ${name}${years}. Preservar a identidade da foto de referência, idade e traços naturais. ${data.outfit==='original'?'Manter a roupa da foto.':'Criar uma roupa coerente com a aventura e mantê-la em todas as páginas.'} Tema: ${cleanText(data.theme)}. ${cast.length?'Elenco de apoio: '+cast.join('; ')+'. ':''}Lição da história: ${feeling}.${cleanText(data.objective)?' Propósito do livro: '+cleanText(data.objective)+'.':''} Idioma do texto final: ${cleanText(data.language)||'português'}. Sem texto, sem marca d'água. Anatomia correta. Composição quadrada.`;const outline=[['Capa',`${name} e a aventura de ${theme}. Apresentar o personagem principal e o mundo da história.`],['Um dia especial',`Apresentar ${name} na rotina e mostrar uma característica: ${cleanText(data.personality)||'curiosidade e imaginação'}.`],['O convite',`Um acontecimento desperta o interesse de ${name} pelo universo de ${theme}.`],['Um mundo para descobrir',`O personagem chega ao cenário da aventura, com detalhes sensoriais adequados à faixa ${cleanText(data.age)}.`],['Um novo encontro',`Apresentar ${cast.length?cast.map(item=>item.split(' (')[0]).join(' e '):'um amigo original da aventura'} e criar uma oportunidade de cooperação.`],['O desafio',`Criar um conflito leve e apropriado para a idade, que permita explorar ${feeling}.`],['A primeira tentativa',`Mostrar a primeira tentativa de resolver o desafio e o que ${name} aprende com ela.`],['Uma boa ideia',`A criança encontra uma solução usando ${feeling} e participa ativamente da decisão.`],['A grande conquista',`Mostrar ${name} como protagonista da solução, com apoio dos amigos e sem resolver tudo por magia.`],['O que ficou no coração',`Encerrar com uma cena acolhedora, reforçando ${feeling}.${cleanText(data.details)?' Incorporar, quando coerente: '+cleanText(data.details)+'.':''}`]];return outline.map(item=>({title:item[0],description:item[1],prompt:base+' Cena: '+item[1]}))}
function adminBriefingHtml(record){const briefing=record.briefing||{};const rows=orderLines(briefing).filter(entry=>cleanText(entry[1])).map(entry=>'<dt>'+escapeHtml(entry[0])+'</dt><dd>'+escapeHtml(entry[1])+'</dd>').join('');const characters=[{name:briefing.name||'Personagem principal',kind:'Principal',detail:briefing.years===''||briefing.years===undefined?'':briefing.years+' anos',photo:briefing.photo||''},...(Array.isArray(briefing.cast)?briefing.cast:[])];const characterCards=characters.map((item,index)=>'<div class="card"><h3>'+escapeHtml(item.name||'Personagem')+'</h3>'+(cleanText(item.photo)?'<img class="photo" src="'+escapeHtml(item.photo)+'" alt="Foto de '+escapeHtml(item.name||'personagem')+'">':'<p class="note">Sem foto de referência</p>')+'<dl><dt>Tipo</dt><dd>'+escapeHtml(index===0?'Personagem principal':item.kind||'Personagem')+'</dd><dt>Detalhe</dt><dd>'+escapeHtml(item.detail||'—')+'</dd></dl></div>').join('');return '<section class="admin-section"><h2>Briefing completo do cliente</h2><div class="card"><dl><dt>Pedido</dt><dd>'+escapeHtml(record.code)+'</dd><dt>Recebido em</dt><dd>'+escapeHtml(new Date(record.createdAt).toLocaleString('pt-BR'))+'</dd>'+rows+'</dl></div></section><section class="admin-section"><h2>Personagens que vão aparecer</h2><div class="photo-grid">'+characterCards+'</div></section>'}
function adminProductionHtml(record,settings){const story=record.story;const statusOptions=ORDER_STATUSES.map(status=>'<option value="'+escapeHtml(status)+'" '+(record.status===status?'selected':'')+'>'+escapeHtml(status)+'</option>').join('');const statusBox='<div class="status-box"><label for="admin-order-status">STATUS DO PEDIDO</label><div class="status-row"><select id="admin-order-status">'+statusOptions+'</select><button id="admin-save-status" type="button">Salvar</button></div><p class="note" id="admin-status-save"></p></div>';const summaryBlock='<section class="admin-section"><h2>Resumo do pedido</h2><div class="card"><pre id="summary">'+escapeHtml(record.summary||'')+'</pre><div class="actions"><button class="secondary" id="copy" type="button">Copiar resumo</button></div></div></section>';const storyBlock=story?'<section class="admin-section"><h2>História ('+escapeHtml(String(story.provider))+(story.mock?' · demonstração':'')+')</h2><div class="card"><dl><dt>Título</dt><dd>'+escapeHtml(story.title)+'</dd><dt>Páginas</dt><dd>'+story.pages.length+'</dd><dt>Prompts</dt><dd>'+story.illustrations.length+'</dd></dl><div class="actions"><button class="primary" id="admin-generate" type="button">Gerar de novo</button><a class="secondary" href="'+escapeHtml('/api/admin/pdf?code='+record.code+'&token='+settings.admin)+'">Baixar PDF</a></div><p class="note" id="admin-status"></p></div><div class="card"><pre>'+escapeHtml(story.pages.map(page=>'P'+page.page+': '+page.text).join('\n\n'))+'</pre></div><h2>Prompts de ilustração</h2><div class="card"><pre>'+escapeHtml(story.illustrations.map(item=>'Página '+item.page+': '+item.prompt).join('\n\n'))+'</pre></div></section>':'<section class="admin-section"><h2>Produção</h2><div class="card"><p class="note">A história deste pedido ainda não foi gerada.</p><div class="actions"><button class="primary" id="admin-generate" type="button">Gerar história (30 páginas)</button></div><p class="note" id="admin-status"></p></div></section>';const sheets='<section class="admin-section"><h2>Cenas de produção</h2><div class="card"><pre>'+escapeHtml(briefingScenes(record.briefing).map(scene=>scene.title+'\n  '+scene.description+'\n  Prompt: '+scene.prompt).join('\n\n'))+'</pre></div></section>';return '<div class="admin-order-head"><div><a class="admin-back" href="/painel?token='+encodeURIComponent(settings.admin)+'">← Voltar ao painel</a><h2 style="font-size:24px;margin:0">Pedido #'+escapeHtml(record.code)+'</h2><p class="note">Visão administrativa · briefing, fotos e produção</p></div>'+statusBox+'</div>'+adminBriefingHtml(record)+summaryBlock+storyBlock+sheets}
function orderPageHtml(record,settings,origin,isAdmin){const briefing=record.briefing||{};const link=origin+orderLink(record.code,record.accessToken||'');const summary=record.summary||orderSummary(briefing,record.code,settings,link);const photo=cleanText(briefing.photo)?'<img class="photo" src="'+escapeHtml(briefing.photo)+'" alt="Foto de referência da criança">':'<p class="note">Nenhuma foto foi anexada a este pedido.</p>';const rows=orderLines(briefing).filter(entry=>cleanText(entry[1])).map(entry=>'<dt>'+escapeHtml(entry[0])+'</dt><dd>'+escapeHtml(entry[1])+'</dd>').join('');const production=isAdmin?adminProductionHtml(record,settings):'';const clientNote=isAdmin?'':'<p class="note">Este é o seu pedido. A loja usa a foto e as respostas para produzir o livro e combina o pagamento pelo WhatsApp. Arquivos de produção não são exibidos aqui.</p>';const adminScript=isAdmin?'<script>var statusSelect=document.getElementById("admin-order-status"),statusSave=document.getElementById("admin-save-status"),statusMsg=document.getElementById("admin-status-save");if(statusSave)statusSave.onclick=function(){statusSave.disabled=true;if(statusMsg)statusMsg.textContent="Salvando…";fetch("'+escapeHtml('/api/admin/status?code='+record.code+'&token='+settings.admin)+'",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({status:statusSelect.value})}).then(function(r){return r.json()}).then(function(payload){statusSave.disabled=false;if(payload&&payload.ok){if(statusMsg)statusMsg.textContent="Status atualizado.";setTimeout(function(){window.location.reload()},500)}else if(statusMsg)statusMsg.textContent=payload&&payload.error?payload.error:"Não foi possível salvar."}).catch(function(){statusSave.disabled=false;if(statusMsg)statusMsg.textContent="Não foi possível salvar."})};var copy=document.getElementById("copy");if(copy)copy.onclick=function(){navigator.clipboard.writeText(document.getElementById("summary").textContent).then(function(){copy.textContent="Resumo copiado"})};var generate=document.getElementById("admin-generate");if(generate)generate.onclick=function(){var status=document.getElementById("admin-status");generate.disabled=true;if(status)status.textContent="Gerando a história…";fetch("'+escapeHtml('/api/admin/book?code='+record.code+'&token='+settings.admin)+'",{method:"POST"}).then(function(r){return r.json()}).then(function(payload){if(payload&&payload.story){window.location.reload()}else{generate.disabled=false;if(status)status.textContent=payload&&payload.error?payload.error:"Não foi possível gerar."}}).catch(function(){generate.disabled=false;if(status)status.textContent="Não foi possível gerar."})};</script>':'';const clientContent='<span class="badge">'+escapeHtml(record.status)+'</span><h1>Pedido '+escapeHtml(record.code)+'</h1><p class="code">'+escapeHtml(new Date(record.createdAt).toLocaleString('pt-BR'))+'</p><div class="actions">'+(customerWhatsAppLink(briefing)?'<a class="primary" href="'+escapeHtml(customerWhatsAppLink(briefing))+'" target="_blank" rel="noopener">Falar com o cliente</a>':'')+'<a class="secondary" href="'+escapeHtml('https://wa.me/?text='+encodeURIComponent(summary))+'" target="_blank" rel="noopener">Encaminhar pedido</a></div><div class="card">'+photo+'<dl>'+rows+'</dl></div>'+((settings.pixCopyPaste||settings.pix)?'<div class="card"><h2 style="margin-top:0">Pagamento via Pix</h2><p class="note">Valor: <strong>'+escapeHtml(settings.price)+'</strong></p>'+(settings.pixCopyPaste?'<p class="pix" style="font-size:11px">'+escapeHtml(settings.pixCopyPaste)+'</p>'+(settings.pix?'<p class="note">Chave Pix: <strong>'+escapeHtml(settings.pix)+'</strong></p>':'')+'<p class="note">Use o Pix Copia e Cola no app do seu banco.</p>':'<p class="pix">'+escapeHtml(settings.pix)+'</p><p class="note">Use esta chave Pix para pagar.</p>')+'</div>':'<div class="card"><h2 style="margin-top:0">Cobrança</h2><p class="note">Valor: '+escapeHtml(settings.price)+' · combine o pagamento pelo WhatsApp.</p></div>')+production+clientNote+'<p class="note">Link privado do pedido: quem tiver este endereço vê a foto e os dados. Não compartilhe fora da produção e apague o pedido depois de entregar.</p>';const top=isAdmin?'<header class="admin-topbar"><div class="admin-brand"><div class="admin-logo">FC</div><div>FC Livros Mágicos<br><span style="font-size:12px;color:#cbd5e1;font-weight:600">Pedido administrativo</span></div></div><div class="admin-topmeta">'+escapeHtml(new Date(record.createdAt).toLocaleString('pt-BR'))+'</div></header><main class="admin-shell">':'';const bottom=isAdmin?'</main>':'';return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Pedido '+escapeHtml(record.code)+' — '+escapeHtml(settings.shop)+'</title><style>'+ORDER_CSS+(isAdmin?ADMIN_CSS:'')+'</style></head><body'+(isAdmin?' class="admin-body"':'')+'>'+top+clientContent+bottom+adminScript+'</body></html>'}
